SELECT 
FROM waitlist_entry w LEFT JOIN shop s ON s.id=w.shop_id LEFT JOIN app_user u ON u.id=w.user_id
WHERE w.id=#{id} AND w.region=#{region}

SELECT 
FROM waitlist_entry w LEFT JOIN shop s ON s.id=w.shop_id LEFT JOIN app_user u ON u.id=w.user_id
WHERE w.id=#{id} AND w.user_id=#{userId} AND w.region=#{region}

SELECT 
FROM waitlist_entry w LEFT JOIN shop s ON s.id=w.shop_id LEFT JOIN app_user u ON u.id=w.user_id
WHERE w.id=#{id} AND w.merchant_id=#{merchantId} AND w.region=#{region}
